void findPeaks() {
	peaks.resize(0);
	int start = 0;
	while (start < bands) {
		if (energy[start] > smoothedEnergy[start]) {
			int end = start;
			Sample bandSum = 0, energySum = 0, observedSum = 0, observedWeight = 0;
			while (end < bands && energy[end] > smoothedEnergy[end]) {
				bandSum += end*energy[end];
				energySum += energy[end];
				// VibeRa experiment: the previous spectrum already carries
				// the expected bin rotation. Residual phase measures the
				// frequency offset from that bin, in cycles per sample.
				int reference = 0;
				Sample strongest = _impl::norm(bandsForChannel(0)[end].input);
				for (int c = 1; c < channels; ++c) {
					Sample weight = _impl::norm(bandsForChannel(c)[end].input);
					if (weight > strongest) { reference = c; strongest = weight; }
				}
				auto &bin = bandsForChannel(reference)[end];
				if (blockProcess.newSpectrum && strongest > noiseFloor &&
					_impl::norm(bin.prevInput) > noiseFloor) {
					Complex residual = _impl::mul<true>(bin.input, bin.prevInput);
					Sample observed = bandToFreq(Sample(end)) +
						std::arg(residual)/(Sample(2*M_PI)*stft.defaultInterval());
					if (std::isfinite(observed) && observed > 0 && observed < Sample(0.5)) {
						observedSum += observed*energy[end];
						observedWeight += energy[end];
					}
				}
				++end;
			}
			Sample avgBand = bandSum/energySum;
			Sample observed = observedWeight > 0 ? observedSum/observedWeight : bandToFreq(avgBand);
			Sample delta = freqToBand(mapFreq(observed)) - freqToBand(observed);
			peaks.emplace_back(Peak{avgBand, avgBand + delta});
			start = end;
		}
		++start;
	}
}
